class Solution {
  public long minSum(int[] nums1, int[] nums2) {
    long a = 0, b = 0;
    int za = 0, zb = 0;
    for (int x : nums1) {
      a += x;
      if (x == 0) za++;
    }
    for (int x : nums2) {
      b += x;
      if (x == 0) zb++;
    }
    if (a + za == b + zb) return a + za;
    if (za == 0 && a < b + zb || zb == 0 && b < a + za) return -1;
    return Math.max(a + za, b + zb);
  }
}
